contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount));
        require(amount > 0);
        require(address(this).balance >= amount, "insufficient balance");

        uint256 beforeBal = address(this).balance;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBal = address(this).balance;

        assert(reverted || afterBal <= beforeBal - amount);
    }

    receive() external payable {}
}

